    g=[r[:] for r in g0]; h=len(g); w=len(g[0]); dirs=[(-1,0),(0,-1),(1,0),(0,1)]
    pos=seed; d=0; arm=1
    while d<maxturns:
        dr,dc=dirs[d%4]
        steps=arm; moved=False
        for _ in range(steps):
            ni,nj=pos[0]+dr,pos[1]+dc
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==0:
                g[ni][nj]=3; pos=(ni,nj); moved=True
            else: break
        d+=1; arm+=1
    return g
